def choose_move(observation):
    def clamp_step(a, b):
        if b > a:
            return 1
        if b < a:
            return -1
        return 0

    def pos(key, default):
        v = observation.get(key, default)
        if isinstance(v, (list, tuple)) and len(v) >= 2:
            return v[0], v[1]
        return default

    def score(p, q):
        return abs(p[0] - q[0]) + abs(p[1] - q[1])

    def step_toward(src, dst):
        return [clamp_step(src[0], dst[0]), clamp_step(src[1], dst[1])]

    def step_away(src, dst):
        return [clamp_step(dst[0], src[0]), clamp_step(dst[1], src[1])]

    env = observation.get("environment_name", "resource_collection")
    sx, sy = pos("self_position", (0, 0))
    ox, oy = pos("opponent_position", (sx, sy))
    self_pos = (sx, sy)
    opp_pos = (ox, oy)

    if env == "pursuit_evasion":
        role = observation.get("self_role", "pursuer")
        if role == "pursuer":
            return step_toward(self_pos, opp_pos)
        w = observation.get("grid_width", 0) or 0
        h = observation.get("grid_height", 0) or 0
        corners = []
        if w and h:
            corners = [(0, 0), (0, h - 1), (w - 1, 0), (w - 1, h - 1)]
        else:
            corners = [(-10, -10), (-10, 10), (10, -10), (10, 10)]
        target = corners[0]
        best = -1
        for c in corners:
            d = score(c, opp_pos)
            if d > best:
                best = d
                target = c
        return step_toward(self_pos, target)

    if env == "territory_control":
        targets = observation.get("unclaimed_cells") or observation.get("opponent_territory") or observation.get("frontier_cells") or []
        if targets:
            best = None
            best_d = None
            for item in targets:
                if isinstance(item, (list, tuple)) and len(item) >= 2:
                    p = (item[0], item[1])
                    d = score(self_pos, p)
                    if best is None or d < best_d:
                        best = p
                        best_d = d
            if best is not None:
                return step_toward(self_pos, best)
        own = observation.get("self_territory") or []
        if own:
            cx = 0
            cy = 0
            n = 0
            for item in own:
                if isinstance(item, (list, tuple)) and len(item) >= 2:
                    cx += item[0]
                    cy += item[1]
                    n += 1
            if n:
                center = (cx // n, cy // n)
                return step_away(self_pos, center)
        return step_toward(self_pos, opp_pos)

    resources = observation.get("resources") or observation.get("resource_cells") or []
    if resources:
        best = None
        best_d = None
        for item in resources:
            if isinstance(item, (list, tuple)) and len(item) >= 2:
                p = (item[0], item[1])
                d = score(self_pos, p)
                if best is None or d < best_d:
                    best = p
                    best_d = d
        if best is not None:
            return step_toward(self_pos, best)

    if score(self_pos, opp_pos) <= 2:
        return step_away(self_pos, opp_pos)

    w = observation.get("grid_width", 0) or 0
    h = observation.get("grid_height", 0) or 0
    if w and h:
        center = (w // 2, h // 2)
        return step_toward(self_pos, center)

    return [0, 0]

